[Function(nameof(OnboardingOrchestrator))]
public static async Task<OnboardingResult> OnboardingOrchestrator(
    [OrchestrationTrigger] TaskOrchestrationContext context)
{
    var request = context.GetInput<OnboardingRequest>();

    // 1. Automated step — runs in an activity, retried automatically
    var credit = await context.CallActivityAsync<CreditResult>(
        nameof(CheckCredit), request, new TaskOptions { Retry = RetryPolicy(...) });

    if (!credit.Approved)
        return new OnboardingResult("Rejected", credit.Reason);

    // 2. Wait for a human, with a deadline — durable, survives restarts
    using var cts = new CancellationTokenSource();
    var approvalTask = context.WaitForExternalEvent<ApprovalDecision>("ManagerApproval");
    var timeoutTask = context.CreateTimer(context.CurrentUtcDateTime.AddDays(3), cts.Token);

    var winner = await Task.WhenAny(approvalTask, timeoutTask);
    if (winner == timeoutTask)
        return new OnboardingResult("Expired", "No manager decision within 3 days");

    cts.Cancel(); // cancel the timer so it does not fire later
    var decision = approvalTask.Result;
    if (!decision.Approved)
        return new OnboardingResult("Rejected", decision.Comment);

    // 3. Fan-out provisioning in parallel
    var tasks = new[]
    {
        context.CallActivityAsync(nameof(ProvisionAdAccount), request),
        context.CallActivityAsync(nameof(ProvisionEmail), request),
        context.CallActivityAsync(nameof(AssignLicenses), request)
    };
    await Task.WhenAll(tasks);

    await context.CallActivityAsync(nameof(SendWelcomeEmail), request);
    return new OnboardingResult("Completed", null);
}

